# 역방향 위상 정렬
# 1. 원래 간선을 뒤집고 outdegree를 계산합니다.
# 2. 안전한 노드를 큐에서 빼며 그 선행 노드의 차수를 줄입니다.
# 3. 차수가 0이 된 노드를 추가하고 안전 배열을 번호순으로 반환합니다.

def safe_topo(graph):
    rev = [[] for _ in graph]
    degree = list(map(len, graph))
    for u, vs in enumerate(graph):
        for v in vs:
            rev[v].append(u)
    q = deque((i for i, d in enumerate(degree) if d == 0))
    safe = [False] * len(graph)
    while q:
        u = q.popleft()
        safe[u] = True
        for v in rev[u]:
            degree[v] -= 1
            if degree[v] == 0:
                q.append(v)
    return [i for i, ok in enumerate(safe) if ok]

class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return safe_topo(graph)

