# 3색 DFS
# 1. state 1로 현재 방문 경로를 표시합니다.
# 2. 모든 이웃이 안전할 때만 state 2로 확정합니다.
# 3. 재귀 깊이가 V까지 커질 수 있으므로 큰 입력은 반복식 방법을 권장합니다.

def safe_dfs(graph):
    state = [0] * len(graph)

    def visit(u):
        if state[u]:
            return state[u] == 2
        state[u] = 1
        if not all((visit(v) for v in graph[u])):
            return False
        state[u] = 2
        return True
    return [u for u in range(len(graph)) if visit(u)]

class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return safe_dfs(graph)

