# 시작점별 부분 그래프 검사
# 1. 도달 집합 reach를 구합니다.
# 2. 그 부분 그래프에 Kahn 알고리즘을 적용합니다.
# 3. 모든 정점이 제거되면 해당 시작점은 안전합니다. 작은 입력에서 검증용으로 좋습니다.

def safe_repeated(graph):
    result = []
    for root in range(len(graph)):
        reach = traverse(graph, root)
        degree = {u: 0 for u in reach}
        for u in reach:
            for v in graph[u]:
                degree[v] += 1
        q = deque((u for u in reach if degree[u] == 0))
        count = 0
        while q:
            u = q.popleft()
            count += 1
            for v in graph[u]:
                degree[v] -= 1
                if degree[v] == 0:
                    q.append(v)
        if count == len(reach):
            result.append(root)
    return result

def traverse(adj, start, bfs=False):
    seen = {start}
    todo = deque([start])
    while todo:
        u = todo.popleft() if bfs else todo.pop()
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                todo.append(v)
    return seen

class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return safe_repeated(graph)

