# 도달 집합의 고정점
# 1. 현재 방문 집합을 복사합니다.
# 2. 그 방들의 모든 열쇠를 합집합으로 추가합니다.
# 3. 변화가 없으면 전체 도달 여부를 반환합니다. 반복 탐색 때문에 느립니다.

def rooms_fixed(rooms):
    seen = {0}
    while True:
        more = set(seen)
        for u in seen:
            more.update(rooms[u])
        if more == seen:
            return len(seen) == len(rooms)
        seen = more

