# 확장 상태 Dijkstra
# 1. 두 시작 상태를 힙에 넣습니다.
# 2. 오래된 거리 항목을 건너뜁니다.
# 3. 반대 색 간선을 완화합니다. 이 문제에서는 BFS가 더 간단합니다.

def alternating(n, red, blue, mode):
    adj = [[[] for _ in range(n)] for _ in range(2)]
    for color, edges in enumerate([red, blue]):
        for u, v in edges:
            adj[color][u].append(v)
    dist = [[float('inf')] * 2 for _ in range(n)]
    dist[0] = [0, 0]
    todo = [(0, 0, 0), (0, 0, 1)]
    while todo:
        length, u, color = heapq.heappop(todo)
        if length != dist[u][color]:
            continue
        for v in adj[1 - color][u]:
            if length + 1 < dist[v][1 - color]:
                dist[v][1 - color] = length + 1
                state = (length + 1, v, 1 - color)
                heapq.heappush(todo, state)
    return [-1 if min(d) == float('inf') else min(d) for d in dist]

class Solution:
    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return alternating(n, redEdges, blueEdges, 'heap')

