# 부모 경로 메모이제이션
# 1. 이미 계산된 조상을 만날 때까지 path에 저장합니다.
# 2. path를 거꾸로 꺼내 arrival 값을 채웁니다.
# 3. 각 직원의 도착 시간은 한 번만 확정됩니다.

def inform_parent(n, head, manager, times):
    arrival = {head: 0}
    for i in range(n):
        path = []
        u = i
        while u not in arrival:
            path.append(u)
            u = manager[u]
        while path:
            v = path.pop()
            p = manager[v]
            arrival[v] = arrival[p] + times[p]
    return max(arrival.values())

class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: List[int], informTime: List[int]) -> int:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return inform_parent(n, headID, manager, informTime)

