# 방향 비용 DFS
# 1. 각 간선을 양쪽 인접 리스트에 비용과 함께 넣습니다.
# 2. 0에서 DFS하며 새 정점으로 가는 비용을 더합니다.
# 3. 트리여서 선택한 부모 경로가 유일합니다.

def reorder(n, edges, mode):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append((v, 1))
        adj[v].append((u, 0))
    todo = deque([0])
    seen = {0}
    answer = 0
    while todo:
        u = todo.pop()
        for v, cost in adj[u]:
            if v not in seen:
                seen.add(v)
                answer += cost
                todo.append(v)
    return answer

class Solution:
