# 부모 배열과 원래 간선 비교
# 1. 무방향으로 탐색해 parent를 저장합니다.
# 2. 원래 간선 u→v에 대해 parent[v]==u인지 확인합니다.
# 3. 그렇다면 자식 방향이므로 반전 개수에 더합니다.

def reorder(n, edges, mode):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append((v, 1))
        adj[v].append((u, 0))
    parent = [-1] * n
    parent[0] = 0
    order = [0]
    for u in order:
        for v, _ in adj[u]:
            if parent[v] == -1:
                parent[v] = u
                order.append(v)
    return sum((parent[v] == u for u, v in edges))

class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return reorder(n, connections, 'parent')

from typing import List
from collections import defaultdict, deque
import heapq
from itertools import combinations

# 간선 제거 후 DSU
# 1. 제외할 간선마다 새 DSU를 만듭니다.
# 2. 나머지 간선을 모두 합칩니다.
# 3. 대표가 두 개 이상이면 제외한 간선이 다리입니다. 검증용 작은 입력에 적합합니다.

def bridges_remove(n, edges):
    result = []
    for skip, edge in enumerate(edges):
        d = DSU(n)
        for i, (u, v) in enumerate(edges):
            if i != skip:
                d.union(u, v)
        if len({d.find(i) for i in range(n)}) > 1:
            result.append(edge)
    return result

class DSU:

    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while x != self.parent[x]:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        a, b = (self.find(a), self.find(b))
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = (b, a)
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

class Solution:
    def criticalConnections(self, n: int, connections: List[List[int]]) -> List[List[int]]:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return bridges_remove(n, connections)

