# 출구들에서 다중 시작 BFS
# 1. 경계의 빈 칸들을 거리 0으로 넣습니다.
# 2. 역방향으로 탐색해 입구를 찾습니다.
# 3. 무방향 이동이므로 같은 최단 거리를 얻습니다.

def nearest(maze, entrance, mode):
    m, n = (len(maze), len(maze[0]))
    start = tuple(entrance)

    def neighbors(u):
        r, c = u
        return [(a, b) for a, b in [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)] if 0 <= a < m and 0 <= b < n and (maze[a][b] == '.')]

    def exit(u):
        return u != start and (u[0] in (0, m - 1) or u[1] in (0, n - 1))
    sources = [(r, c) for r in range(m) for c in range(n) if maze[r][c] == '.' and exit((r, c))]
    todo = deque(((0, u) for u in sources))
    seen = set(sources)
    while todo:
        dist, u = todo.popleft()
        if u == start:
            return dist
        for v in neighbors(u):
            if v not in seen:
                seen.add(v)
                todo.append((dist + 1, v))
    return -1

class Solution:
    def nearestExit(self, maze: List[List[str]], entrance: List[int]) -> int:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return nearest(maze, entrance, 'reverse')

