# Dijkstra
# 1. 힙의 첫 항목을 거리로 둡니다.
# 2. 단위 비용 이동을 확장합니다.
# 3. 이 문제에서는 동일 비용이라 BFS가 더 효율적입니다.

def nearest(maze, entrance, mode):
    m, n = (len(maze), len(maze[0]))
    start = tuple(entrance)

    def neighbors(u):
        r, c = u
        return [(a, b) for a, b in [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)] if 0 <= a < m and 0 <= b < n and (maze[a][b] == '.')]

    def exit(u):
        return u != start and (u[0] in (0, m - 1) or u[1] in (0, n - 1))
    sources = [start]
    todo = [(0, u) for u in sources]
    seen = set(sources)
    while todo:
        dist, u = heapq.heappop(todo)
        if exit(u):
            return dist
        for v in neighbors(u):
            if v not in seen:
                seen.add(v)
                heapq.heappush(todo, (dist + 1, v))
    return -1

