# 계정 DSU
# 1. 이메일→계정 사전을 만듭니다.
# 2. 같은 이메일의 계정 인덱스를 union합니다.
# 3. 최종 대표별 이메일을 모아 정렬합니다.

def merge_accounts(accounts, mode):
    owner = {}
    d = DSU(len(accounts))
    for i, account in enumerate(accounts):
        for email in account[1:]:
            if email in owner:
                d.union(i, owner[email])
            owner[email] = i
    buckets = defaultdict(list)
    for email, i in owner.items():
        buckets[d.find(i)].append(email)
    return [[accounts[root][0]] + sorted(emails) for root, emails in buckets.items()]

class DSU:

    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while x != self.parent[x]:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        a, b = (self.find(a), self.find(b))
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = (b, a)
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

class Solution:
    def accountsMerge(self, accounts: List[List[str]]) -> List[List[str]]:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return merge_accounts(accounts, 'dsu')

