# Union-Find
# 1. 문자를 0~25로 바꿉니다.
# 2. ==만 먼저 union합니다.
# 3. !=인데 대표가 같으면 False입니다.

def equations_possible(equations, mode):
    d = DSU(26)
    for e in equations:
        if e[1] == '=':
            d.union(ord(e[0]) - 97, ord(e[3]) - 97)
    return all((e[1] == '=' or d.find(ord(e[0]) - 97) != d.find(ord(e[3]) - 97) for e in equations))

class DSU:

    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while x != self.parent[x]:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        a, b = (self.find(a), self.find(b))
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = (b, a)
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

class Solution:
    def equationsPossible(self, equations: List[str]) -> bool:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return equations_possible(equations, 'dsu')

