# 전이 폐쇄
# 1. 자기 자신과 등식 쌍을 True로 둡니다.
# 2. i→k와 k→j가 참이면 i→j도 참입니다.
# 3. 모든 부등식이 False 관계인지 검사합니다. Σ=26이라 가능합니다.

def equations_possible(equations, mode):
    adj = [set([i]) for i in range(26)]
    for e in equations:
        if e[1] == '=':
            a, b = (ord(e[0]) - 97, ord(e[3]) - 97)
            adj[a].add(b)
            adj[b].add(a)
    reach = [[j in adj[i] for j in range(26)] for i in range(26)]
    for k in range(26):
        for i in range(26):
            for j in range(26):
                reach[i][j] |= reach[i][k] and reach[k][j]
    return all((e[1] == '=' or not reach[ord(e[0]) - 97][ord(e[3]) - 97] for e in equations))

