def equivalent(s1, s2, base, mode):
    d = DSU(26)
    for a, b in zip(s1, s2):
        d.union(ord(a) - 97, ord(b) - 97)
    minimum = {}
    for i in range(26):
        minimum[d.find(i)] = min(minimum.get(d.find(i), i), i)
    return ''.join((chr(97 + minimum[d.find(ord(c) - 97)]) for c in base))

class DSU:

    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while x != self.parent[x]:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        a, b = (self.find(a), self.find(b))
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = (b, a)
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

