def alien(words, mode):
    chars = sorted(set(''.join(words)))
    index = {c: i for i, c in enumerate(chars)}
    edges = set()
    for a, b in zip(words, words[1:]):
        for x, y in zip(a, b):
            if x != y:
                edges.add((index[x], index[y]))
                break
        else:
            if len(a) > len(b):
                return ''
    order = topo_order(len(chars), edges, 'queue')
    return ''.join((chars[i] for i in order))

def topo_order(n, edges, mode='queue'):
    adj = [[] for _ in range(n)]
    degree = [0] * n
    for u, v in edges:
        adj[u].append(v)
        degree[v] += 1
    todo = [i for i in range(n) if degree[i] == 0]
    todo = deque(todo)
    order = []
    while todo:
        u = todo.popleft()
        order.append(u)
        for v in adj[u]:
            degree[v] -= 1
            if degree[v] == 0:
                todo.append(v)
    return order if len(order) == n else []

