    adj = [[] for _ in range(n)]
    degree = [0] * n
    for u, v in edges:
        adj[u].append(v)
        degree[v] += 1
    todo = [i for i in range(n) if degree[i] == 0]
    heapq.heapify(todo)
    order = []
    while todo:
        u = heapq.heappop(todo)
        order.append(u)
        for v in adj[u]:
            degree[v] -= 1
            if degree[v] == 0:
                heapq.heappush(todo, v)
    return order if len(order) == n else []

