def grouped_items(n, m, group, before, mode):
    group = list(group)
    for i in range(n):
        if group[i] == -1:
            group[i] = m
            m += 1
    item_edges = []
    group_edges = set()
    for v, previous in enumerate(before):
        for u in previous:
            item_edges.append((u, v))
            if group[u] != group[v]:
                group_edges.add((group[u], group[v]))
    item_order = topo_order(n, item_edges, 'heap')
    group_order = topo_order(m, group_edges, 'heap')
    if len(item_order) != n or len(group_order) != m:
        return []
    buckets = defaultdict(list)
    for i in item_order:
        buckets[group[i]].append(i)
    return [i for g in group_order for i in buckets[g]]

def topo_order(n, edges, mode='queue'):
    adj = [[] for _ in range(n)]
    degree = [0] * n
    for u, v in edges:
        adj[u].append(v)
        degree[v] += 1
    todo = [i for i in range(n) if degree[i] == 0]
    heapq.heapify(todo)
    order = []
    while todo:
        u = heapq.heappop(todo)
        order.append(u)
        for v in adj[u]:
            degree[v] -= 1
            if degree[v] == 0:
                heapq.heappush(todo, v)
    return order if len(order) == n else []

