# 간선 수를 포함한 Dijkstra
# 1. 비용이 작은 상태부터 힙에서 꺼냅니다.
# 2. used가 k+1이면 더 확장하지 않습니다.
# 3. 같은 도시에 도착해도 간선 수가 다르면 다른 상태입니다.

def cheapest(n, flights, src, dst, k, mode):
    adj = [[] for _ in range(n)]
    for u, v, c in flights:
        adj[u].append((v, c))
    best = {(src, 0): 0}
    heap = [(0, src, 0)]
    answer = float('inf')
    while heap:
        cost, u, used = heapq.heappop(heap)
        if cost != best[u, used]:
            continue
        if u == dst:
            answer = cost
            break
        if used == k + 1:
            continue
        for v, c in adj[u]:
            key = (v, used + 1)
            if cost + c < best.get(key, float('inf')):
                best[key] = cost + c
                heapq.heappush(heap, (cost + c, v, used + 1))
    return -1 if answer == float('inf') else answer

