# 남은 간선 수 DP
# 1. 목적지에 도착하면 0입니다.
# 2. 남은 간선이 0이면 실패합니다.
# 3. 각 다음 항공편 비용 + 하위 문제의 최솟값을 저장합니다.

def cheapest(n, flights, src, dst, k, mode):
    adj = [[] for _ in range(n)]
    for u, v, c in flights:
        adj[u].append((v, c))
    from functools import lru_cache

    @lru_cache(None)
    def solve(u, left):
        if u == dst:
            return 0
        if left == 0:
            return float('inf')
        return min((c + solve(v, left - 1) for v, c in adj[u]), default=float('inf'))
    answer = solve(src, k + 1)
    return -1 if answer == float('inf') else answer

