# 최대 힙 Dijkstra
# 1. 시작 확률을 1로 둡니다.
# 2. Python 최소 힙에 음수 확률을 넣습니다.
# 3. 현재 확률×간선 확률이 개선되면 갱신합니다.

def probability(n, edges, probs, start, end, mode):
    adj = [[] for _ in range(n)]
    for (u, v), p in zip(edges, probs):
        adj[u].append((v, p))
        adj[v].append((u, p))
    best = [0.0] * n
    best[start] = 1.0
    heap = [(-1.0, start)]
    while heap:
        neg, u = heapq.heappop(heap)
        value = -neg
        if value < best[u]:
            continue
        if u == end:
            return value
        for v, p in adj[u]:
            if value * p > best[v]:
                best[v] = value * p
                heapq.heappush(heap, (-best[v], v))
    return best[end]

