# 힙 Dijkstra
# 1. 네 방향으로 벽·경계까지 굴려 도착점과 이동 거리를 계산합니다.
# 2. 더 좋은 (거리, 경로)만 best에 저장합니다.
# 3. 목표 상태를 꺼냈을 때 반환합니다. V=RC, L=max(R,C), P=최대 명령 길이입니다.

def rolling(maze, start, target, mode, hole=False):
    m, n = (len(maze), len(maze[0]))
    start = tuple(start)
    target = tuple(target)
    directions = [('d', 1, 0), ('l', 0, -1), ('r', 0, 1), ('u', -1, 0)]

    def moves(u):
        for letter, dr, dc in directions:
            r, c = u
            steps = 0
            while 0 <= r + dr < m and 0 <= c + dc < n and (maze[r + dr][c + dc] == 0):
                r += dr
                c += dc
                steps += 1
            if steps:
                yield ((r, c), steps, letter)
    best = {start: (0, '')}
    heap = [(0, '', start)]
    while heap:
        d, path, u = heapq.heappop(heap)
        if (d, path) != best[u]:
            continue
        if u == target:
            return d
        for v, c, letter in moves(u):
            cand = (d + c, '')
            if cand < best.get(v, (float('inf'), '')):
                best[v] = cand
                heapq.heappush(heap, (*cand, v))
    result = best.get(target)
    return result[0] if result else -1

