# 큐 기반 반복 완화
# 1. 큐에서 꺼낸 상태의 모든 구르기 이동을 계산합니다.
# 2. 거리 또는 동률 문자열이 개선되면 재삽입합니다.
# 3. 일반 BFS처럼 한 번 방문 후 끝내면 안 됩니다. 499는 문자열 개선까지 있어 큰 입력에는 힙을 권장합니다.

def rolling(maze, start, target, mode, hole=False):
    m, n = (len(maze), len(maze[0]))
    start = tuple(start)
    target = tuple(target)
    directions = [('d', 1, 0), ('l', 0, -1), ('r', 0, 1), ('u', -1, 0)]

    def moves(u):
        for letter, dr, dc in directions:
            r, c = u
            steps = 0
            while 0 <= r + dr < m and 0 <= c + dc < n and (maze[r + dr][c + dc] == 0):
                r += dr
                c += dc
                steps += 1
            if steps:
                yield ((r, c), steps, letter)
    best = {start: (0, '')}
    q = deque([start])
    queued = {start}
    while q:
        u = q.popleft()
        queued.remove(u)
        d, path = best[u]
        for v, c, letter in moves(u):
            cand = (d + c, '')
            if cand < best.get(v, (float('inf'), '')):
                best[v] = cand
                if v not in queued:
                    q.append(v)
                    queued.add(v)
    result = best.get(target)
    return result[0] if result else -1

