# Kruskal + DSU
# 1. 모든 간선을 비용순으로 정렬합니다.
# 2. 두 대표가 다를 때만 비용을 더하고 union합니다.
# 3. V-1개가 선택되면 MST입니다. 1168의 V,E에는 가상 정점·우물 간선도 포함합니다.

def cities(n, edges, mode):
    return mst(n, [(u - 1, v - 1, w) for u, v, w in edges], 'kruskal')

def mst(n, edges, mode):
    d = DSU(n)
    total = 0
    count = 0
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        if d.union(u, v):
            total += w
            count += 1
    return total if count == n - 1 else -1

class DSU:

    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while x != self.parent[x]:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        a, b = (self.find(a), self.find(b))
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = (b, a)
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

class Solution:
    def minimumCost(self, n: int, connections: List[List[int]]) -> int:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return cities(n, connections, 'kruskal')

