# Prim 최소 힙
# 1. 한 정점을 비용 0으로 힙에 넣습니다.
# 2. 미방문 정점이면 비용을 더하고 새 간선을 넣습니다.
# 3. 모든 정점을 방문했는지 검사합니다.

def cities(n, edges, mode):
    return mst(n, [(u - 1, v - 1, w) for u, v, w in edges], 'prim')

def mst(n, edges, mode):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
    heap = [(0, 0)]
    seen = set()
    total = 0
    while heap:
        w, u = heapq.heappop(heap)
        if u in seen:
            continue
        seen.add(u)
        total += w
        for v, c in adj[u]:
            if v not in seen:
                heapq.heappush(heap, (c, v))
    return total if len(seen) == n else -1

class Solution:
    def minimumCost(self, n: int, connections: List[List[int]]) -> int:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return cities(n, connections, 'prim')

