# Borůvka
# 1. 각 회차에 전체 간선을 훑어 성분별 최소 간선을 찾습니다.
# 2. 선택한 간선을 DSU로 중복 병합 없이 반영합니다.
# 3. 회차마다 성분 수가 줄며, 합칠 간선이 없으면 연결 불가능입니다.

def cities(n, edges, mode):
    return mst(n, [(u - 1, v - 1, w) for u, v, w in edges], 'boruvka')

def mst(n, edges, mode):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
    d = DSU(n)
    components = n
    total = 0
    while components > 1:
        cheapest = {}
        for u, v, w in edges:
            a, b = (d.find(u), d.find(v))
