# 간선 제외·강제 포함 Kruskal
# 1. 먼저 최적 비용을 계산합니다.
# 2. 제외 시 비용 증가 또는 단절이면 critical입니다.
# 3. 그 외 강제 포함해도 최적 비용이면 pseudo-critical입니다. 이 코드에서는 매 호출마다 정렬합니다.

def classify_mst(n, edges, mode):

    def build(skip=-1, force=-1):
        d = DSU(n)
        cost = 0
        count = 0
        if force >= 0:
            u, v, w = edges[force]
            d.union(u, v)
            cost += w
            count += 1
        for i in sorted(range(len(edges)), key=lambda i: edges[i][2]):
            if i == skip or i == force:
                continue
            u, v, w = edges[i]
            if d.union(u, v):
                cost += w
                count += 1
        return cost if count == n - 1 else float('inf')
    baseline = build()
    critical = []
    pseudo = []
    for i in range(len(edges)):
        if build(skip=i) > baseline:
            critical.append(i)
        elif build(force=i) == baseline:
            pseudo.append(i)
    return [critical, pseudo]

class DSU:

    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while x != self.parent[x]:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        a, b = (self.find(a), self.find(b))
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = (b, a)
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

class Solution:
    def findCriticalAndPseudoCriticalEdges(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return classify_mst(n, edges, 'repeat')

from typing import List
