# 동일 가중치 묶음 + 축약 그래프
# 1. 각 가중치 묶음을 처리하기 전에 DSU 대표로 간선을 축약합니다.
# 2. 후보 간선을 하나씩 제외해 양 끝 연결 여부로 다리를 판정합니다.
# 3. 묶음 검사가 끝난 다음 union합니다. 평행 간선은 원래 ID로 구분합니다.

def classify_mst(n, edges, mode):

    def build(skip=-1, force=-1):
        d = DSU(n)
        cost = 0
        count = 0
        if force >= 0:
            u, v, w = edges[force]
            d.union(u, v)
            cost += w
            count += 1
        for i in sorted(range(len(edges)), key=lambda i: edges[i][2]):
            if i == skip or i == force:
                continue
            u, v, w = edges[i]
            if d.union(u, v):
                cost += w
                count += 1
        return cost if count == n - 1 else float('inf')
    d = DSU(n)
    critical = []
    pseudo = []
    byweight = defaultdict(list)
    for i, (u, v, w) in enumerate(edges):
        byweight[w].append(i)
    for w, ids in sorted(byweight.items()):
        candidates = []
        for i in ids:
            u, v, _ = edges[i]
            a, b = (d.find(u), d.find(v))
            if a != b:
                candidates.append((a, b, i))
        for a, b, i in candidates:
            adj = defaultdict(list)
            for x, y, j in candidates:
                if i != j:
                    adj[x].append(y)
                    adj[y].append(x)
            if b not in traverse(adj, a):
                critical.append(i)
            else:
                pseudo.append(i)
        for a, b, i in candidates:
            d.union(a, b)
    return [critical, pseudo]

class DSU:

    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while x != self.parent[x]:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        a, b = (self.find(a), self.find(b))
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = (b, a)
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

def traverse(adj, start, bfs=False):
    seen = {start}
    todo = deque([start])
    while todo:
        u = todo.popleft() if bfs else todo.pop()
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                todo.append(v)
    return seen

class Solution:
    def findCriticalAndPseudoCriticalEdges(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return classify_mst(n, edges, 'groups')

