# 신장 트리 전수 조사 · 작은 입력 전용
# 1. 각 조합이 순환 없는 연결 구조인지 DSU로 검사합니다.
# 2. 최소 비용 트리만 저장합니다.
# 3. 교집합은 critical, 합집합에서 교집합을 뺀 것은 pseudo입니다. T는 최적 트리 수이며 최대 제약에는 실행하면 안 됩니다.

def classify_mst(n, edges, mode):

    def build(skip=-1, force=-1):
        d = DSU(n)
        cost = 0
        count = 0
        if force >= 0:
            u, v, w = edges[force]
            d.union(u, v)
            cost += w
            count += 1
        for i in sorted(range(len(edges)), key=lambda i: edges[i][2]):
            if i == skip or i == force:
                continue
            u, v, w = edges[i]
            if d.union(u, v):
                cost += w
                count += 1
        return cost if count == n - 1 else float('inf')
    best = float('inf')
    trees = []
    for chosen in combinations(range(len(edges)), n - 1):
        d = DSU(n)
        cost = 0
        for i in chosen:
            u, v, w = edges[i]
            if not d.union(u, v):
                break
            cost += w
        else:
            if cost < best:
                best = cost
                trees = [set(chosen)]
            elif cost == best:
                trees.append(set(chosen))
    every = set.intersection(*trees)
    some = set.union(*trees)
    return [sorted(every), sorted(some - every)]

class DSU:

    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while x != self.parent[x]:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        a, b = (self.find(a), self.find(b))
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = (b, a)
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

class Solution:
    def findCriticalAndPseudoCriticalEdges(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return classify_mst(n, edges, 'enumerate')

