# 1. 한 정점을 비용 0으로 힙에 넣습니다.
# 2. 미방문 정점이면 비용을 더하고 새 간선을 넣습니다.
# 3. 모든 정점을 방문했는지 검사합니다.

def water(n, wells, pipes, mode):
    return mst(n + 1, [(0, i + 1, w) for i, w in enumerate(wells)] + [tuple(e) for e in pipes], 'prim')

def mst(n, edges, mode):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
    heap = [(0, 0)]
    seen = set()
    total = 0
    while heap:
        w, u = heapq.heappop(heap)
        if u in seen:
            continue
        seen.add(u)
        total += w
        for v, c in adj[u]:
            if v not in seen:
                heapq.heappush(heap, (c, v))
    return total if len(seen) == n else -1

class Solution:
    def minCostToSupplyWater(self, n: int, wells: List[int], pipes: List[List[int]]) -> int:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return water(n, wells, pipes, 'prim')

from typing import List
from collections import defaultdict, deque
import heapq
from itertools import combinations

# Borůvka
# 1. 각 회차에 전체 간선을 훑어 성분별 최소 간선을 찾습니다.
# 2. 선택한 간선을 DSU로 중복 병합 없이 반영합니다.
# 3. 회차마다 성분 수가 줄며, 합칠 간선이 없으면 연결 불가능입니다.

def water(n, wells, pipes, mode):
    return mst(n + 1, [(0, i + 1, w) for i, w in enumerate(wells)] + [tuple(e) for e in pipes], 'boruvka')

def mst(n, edges, mode):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
    d = DSU(n)
    components = n
    total = 0
    while components > 1:
        cheapest = {}
        for u, v, w in edges:
            a, b = (d.find(u), d.find(v))
            if a == b:
                continue
            for root in (a, b):
                if root not in cheapest or w < cheapest[root][2]:
                    cheapest[root] = (u, v, w)
        if not cheapest:
            return -1
        for u, v, w in cheapest.values():
            if d.union(u, v):
                total += w
                components -= 1
    return total

class DSU:

    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while x != self.parent[x]:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        a, b = (self.find(a), self.find(b))
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = (b, a)
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

class Solution:
    def minCostToSupplyWater(self, n: int, wells: List[int], pipes: List[List[int]]) -> int:
        # 아래 함수는 이 방법의 핵심 알고리즘입니다.
        return water(n, wells, pipes, 'boruvka')
